int portions(const std::string& name);
}

namespace report {
std::string render(const std::vector<std::string>& names);
}

class Brewing {
public:
    virtual ~Brewing() = default;
    virtual std::string brew(const std::vector<std::string>& names) const = 0;
}

class Brewer final : public Brewing {
public:
    std::string brew(const std::vector<std::string>& names) const override {
        if (names.empty()) return report::render({});
        std::vector<std::string> valid;
        std::copy_if(names.begin(), names.end(), std::back_inserter(valid),
            [](const std::string& name) { return recipe::portions(name) > 0; });
        return report::render(valid);
    }

    int retry(int attempts) const {
        if (attempts <= 0) return 0;
        return 1 + retry(attempts - 1);
    }

    int score(const std::vector<std::vector<std::string>>& batches) const {
        int result = 0;
        for (const auto& batch : batches) {
            for (const auto& name : batch) {
                const int count = recipe::portions(name);
                if (count > 0 && count <= 3) {
                    result += count;
                }
            }
        }
        return result;
    }
}

namespace report {
std::string render(const std::vector<std::string>& names);
}

namespace recipe {
int portions(const std::string& name) {
    enum class Kind { invalid, espresso, filter };
    const auto kind = name == "espresso" ? Kind::espresso
        : name == "filter" ? Kind::filter : Kind::invalid;
    switch (kind) {
        case Kind::espresso: return 2;
        case Kind::filter: return 3;
        default: return 0;
    }
}

std::string preview(const std::string& name) {
    return report::render({name});
}
}

namespace recipe {
int portions(const std::string& name);
}

namespace report {
int total(const std::vector<std::string>& names) {
    return std::accumulate(names.begin(), names.end(), 0,
        [](int sum, const std::string& name) { return sum + recipe::portions(name); });
}

std::string render(const std::vector<std::string>& names) {
    std::ostringstream output;
    output << "coffee:";
    const char* separator = "";
    for (const auto& name : names) {
        output << separator << name << '=' << recipe::portions(name);
        separator = ",";
    }
    output << ";total=" << total(names);
    return output.str();
}
}

